        self.slots, self.types = {}, {}
        plan = parent.machine_plan or {}
        self.value_registers = plan.get("value_registers", {}).get(fn["name"], {})
        self.scalar_select = plan.get("instruction_selection", {}).get("scalar_select", "branch")
